alter sequence counter as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1000 cache 1 no cycle;
do $reylo$ declare s regclass := 'public.counter'; stands numeric; goal numeric; begin execute format('select case when is_called then last_value::numeric + 1 else last_value end from %s', s) into stands; select 1000 into goal; if goal > stands then perform setval(s, goal::bigint, false); end if; end $reylo$;
alter sequence counter_ahead as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1000 cache 1 no cycle;
do $reylo$ declare s regclass := 'public.counter_ahead'; stands numeric; goal numeric; begin execute format('select case when is_called then last_value::numeric + 1 else last_value end from %s', s) into stands; select 1000 into goal; if goal > stands then perform setval(s, goal::bigint, false); end if; end $reylo$;
alter table ahead alter column id set start with 1000;
do $reylo$ declare s regclass := pg_get_serial_sequence('public.ahead', 'id'); stands numeric; goal numeric; begin execute format('select case when is_called then last_value::numeric + 1 else last_value end from %s', s) into stands; select greatest(1000, max(id) + 1) from public.ahead into goal; if goal > stands then perform setval(s, goal::bigint, false); end if; end $reylo$;
alter table down alter column id set start with -1000;
do $reylo$ declare s regclass := pg_get_serial_sequence('public.down', 'id'); stands numeric; goal numeric; begin execute format('select case when is_called then last_value::numeric + -1 else last_value end from %s', s) into stands; select least(-1000, min(id) - 1) from public.down into goal; if goal < stands then perform setval(s, goal::bigint, false); end if; end $reylo$;
alter table explicit alter column id set increment by 10 set start with 1000;
do $reylo$ declare s regclass := pg_get_serial_sequence('public.explicit', 'id'); stands numeric; goal numeric; begin execute format('select case when is_called then last_value::numeric + 10 else last_value end from %s', s) into stands; select greatest(1000, max(id) + 1) from public.explicit into goal; if goal > stands then perform setval(s, goal::bigint, false); end if; end $reylo$;
alter table fresh alter column id set generated by default set increment by 10 set start with 1000;
